//! Produces the generated files in memory: one `.ts` file per type plus an `index.ts` barrel.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU32, Ordering};

use anyhow::{Context, Result};
use ts_rs::{Config, TS};

use crate::sync::read_ts_files;

/// Generated files, keyed by file name, in a stable order.
pub(crate) type Files = BTreeMap<String, String>;

/// Name of the barrel file that re-exports every generated type.
const BARREL: &str = "index.ts";

/// Generates every binding reachable from the root types.
///
/// ts-rs only exports to disk, so types go to a scratch directory first and are
/// read back. Large integers become `number`: plan values (milliseconds, counts)
/// stay far below 2^53, and `serde_json` writes them as plain numbers.
pub(crate) fn generate() -> Result<Files> {
    let scratch = Scratch::new()?;
    let cfg = Config::new()
        .with_large_int("number")
        .with_out_dir(scratch.path());

    // Roots: everything else is pulled in as a dependency.
    barrage_plan::Plan::export_all(&cfg).context("exporting Plan")?;

    let mut files = read_ts_files(scratch.path())?;
    files.insert(BARREL.to_owned(), barrel(&files));
    Ok(files)
}

/// `export type { X } from "./X";` for every generated type.
fn barrel(files: &Files) -> String {
    let mut out = String::from(
        "// This file was generated by barrage-typegen (`just types`). Do not edit this file manually.\n\n",
    );
    for name in files.keys() {
        let ty = name.trim_end_matches(".ts");
        out.push_str(&format!("export type {{ {ty} }} from \"./{ty}\";\n"));
    }
    out
}

/// A scratch directory under the system temp dir, unique per call, removed on drop.
struct Scratch(PathBuf);

impl Scratch {
    fn new() -> Result<Self> {
        static NEXT: AtomicU32 = AtomicU32::new(0);
        let n = NEXT.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!("barrage-typegen-{}-{n}", std::process::id()));
        if path.exists() {
            fs::remove_dir_all(&path)?;
        }
        fs::create_dir_all(&path).with_context(|| format!("creating {}", path.display()))?;
        Ok(Self(path))
    }

    fn path(&self) -> &Path {
        &self.0
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        // Best effort: a leftover temp dir is harmless.
        let _ = fs::remove_dir_all(&self.0);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generates_plan_and_a_barrel_exporting_every_type() {
        let files = generate().unwrap();
        assert!(files.contains_key("Plan.ts"));
        let index = &files[BARREL];
        for name in files.keys().filter(|n| *n != BARREL) {
            let ty = name.trim_end_matches(".ts");
            assert!(index.contains(&format!("export type {{ {ty} }} from \"./{ty}\";")));
        }
    }

    #[test]
    fn large_integers_are_numbers_and_options_are_never_null() {
        let files = generate().unwrap();
        for (name, content) in &files {
            assert!(!content.contains("bigint"), "{name} uses bigint");
            assert!(!content.contains("null"), "{name} allows null");
        }
    }
}
